package com.ultras.bans.database;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.*; import java.io.File; import java.sql.*; import java.time.Instant; import java.util.*; import java.util.concurrent.*;
public final class Database {
 private final ULTRASBansPlugin plugin; private Connection conn; private final ExecutorService executor=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"ULTRAS-BANS-DB");t.setDaemon(true);return t;});
 public Database(ULTRASBansPlugin p){plugin=p;}
 public void init() throws Exception { var c=plugin.configs().get("database.yml"); String type=c.getString("type","sqlite"); if(type.equalsIgnoreCase("mysql")){String url="jdbc:mysql://"+c.getString("mysql.host","localhost")+":"+c.getInt("mysql.port",3306)+"/"+c.getString("mysql.database","ultras_bans")+"?useSSL=false&serverTimezone=UTC"; conn=DriverManager.getConnection(url,c.getString("mysql.username"),c.getString("mysql.password",""));} else {File f=new File(plugin.getDataFolder(),c.getString("sqlite-file","data.db")); conn=DriverManager.getConnection("jdbc:sqlite:"+f);}
 try(Statement s=conn.createStatement()){if(type.equalsIgnoreCase("sqlite"))s.executeUpdate("PRAGMA foreign_keys=ON"); s.executeUpdate("CREATE TABLE IF NOT EXISTS players(uuid TEXT PRIMARY KEY,username TEXT,ip TEXT,platform TEXT,rank_name TEXT,op INTEGER,server TEXT,world TEXT,location TEXT,first_join INTEGER,last_join INTEGER,last_quit INTEGER)"); s.executeUpdate("CREATE TABLE IF NOT EXISTS punishments(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT,username TEXT,ip TEXT,type TEXT,permanent INTEGER,duration_seconds INTEGER,created_at INTEGER,expires_at INTEGER,reason TEXT,operator_name TEXT,operator_uuid TEXT,server TEXT,world TEXT,location TEXT,source TEXT,status TEXT)"); s.executeUpdate("CREATE INDEX IF NOT EXISTS idx_pun_uuid_type ON punishments(uuid,type,status)"); s.executeUpdate("CREATE TABLE IF NOT EXISTS staff_actions(id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT,actor_uuid TEXT,action TEXT,target TEXT,created_at INTEGER,server TEXT,details TEXT)"); s.executeUpdate("CREATE TABLE IF NOT EXISTS jail_inventory(uuid TEXT PRIMARY KEY,data TEXT,location TEXT)"); s.executeUpdate("CREATE TABLE IF NOT EXISTS vanish_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,uuid TEXT,username TEXT,enabled INTEGER,created_at INTEGER,operator_name TEXT,server TEXT,reason TEXT)"); }
 }
 public CompletableFuture<Void> upsertPlayer(PlayerRecord p){return CompletableFuture.runAsync(()->{try{try(PreparedStatement q=conn.prepareStatement("UPDATE players SET username=?,ip=?,platform=?,rank_name=?,op=?,server=?,world=?,location=?,last_join=?,last_quit=? WHERE uuid=?")){q.setString(1,p.username());q.setString(2,p.ip());q.setString(3,p.platform());q.setString(4,p.rank());q.setInt(5,p.op()?1:0);q.setString(6,p.server());q.setString(7,p.world());q.setString(8,p.location());q.setLong(9,p.lastJoin()==null?0:p.lastJoin().toEpochMilli());q.setLong(10,p.lastQuit()==null?0:p.lastQuit().toEpochMilli());q.setString(11,p.uuid().toString());if(q.executeUpdate()>0)return;}try(PreparedStatement s=conn.prepareStatement("INSERT INTO players(uuid,username,ip,platform,rank_name,op,server,world,location,first_join,last_join,last_quit) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)")){s.setString(1,p.uuid().toString());s.setString(2,p.username());s.setString(3,p.ip());s.setString(4,p.platform());s.setString(5,p.rank());s.setInt(6,p.op()?1:0);s.setString(7,p.server());s.setString(8,p.world());s.setString(9,p.location());s.setLong(10,p.firstJoin()==null?System.currentTimeMillis():p.firstJoin().toEpochMilli());s.setLong(11,p.lastJoin()==null?0:p.lastJoin().toEpochMilli());s.setLong(12,p.lastQuit()==null?0:p.lastQuit().toEpochMilli());s.executeUpdate();}}catch(SQLException e){throw new CompletionException(e);}},executor);}
 public CompletableFuture<Long> insertPunishment(PunishmentRecord p){return CompletableFuture.supplyAsync(()->{try(PreparedStatement s=conn.prepareStatement("INSERT INTO punishments(uuid,username,ip,type,permanent,duration_seconds,created_at,expires_at,reason,operator_name,operator_uuid,server,world,location,source,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,p.uuid().toString());s.setString(2,p.username());s.setString(3,p.ip());s.setString(4,p.type().name());s.setInt(5,p.permanent()?1:0);s.setLong(6,p.durationSeconds());s.setLong(7,p.createdAt().toEpochMilli());s.setLong(8,p.expiresAt()==null?0:p.expiresAt().toEpochMilli());s.setString(9,p.reason());s.setString(10,p.operator());s.setString(11,p.operatorUuid()==null?null:p.operatorUuid().toString());s.setString(12,p.server());s.setString(13,p.world());s.setString(14,p.location());s.setString(15,p.source());s.setString(16,p.status().name());s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){return r.next()?r.getLong(1):0;}}catch(SQLException e){throw new CompletionException(e);}},executor);}
 public CompletableFuture<Optional<PunishmentRecord>> active(UUID u,PunishmentType t){return CompletableFuture.supplyAsync(()->{try(PreparedStatement s=conn.prepareStatement("SELECT * FROM punishments WHERE uuid=? AND type=? AND status='ACTIVE' ORDER BY id DESC LIMIT 1")){s.setString(1,u.toString());s.setString(2,t.name());try(ResultSet r=s.executeQuery()){if(!r.next())return Optional.empty(); return Optional.of(read(r));}}catch(SQLException e){throw new CompletionException(e);}},executor);}
 public CompletableFuture<Optional<PunishmentRecord>> activeIp(String ip){return CompletableFuture.supplyAsync(()->{try(PreparedStatement s=conn.prepareStatement("SELECT * FROM punishments WHERE ip=? AND type='IP_BAN' AND status='ACTIVE' ORDER BY id DESC LIMIT 1")){s.setString(1,ip);try(ResultSet r=s.executeQuery()){if(!r.next())return Optional.empty();return Optional.of(read(r));}}catch(SQLException e){throw new CompletionException(e);}},executor);}
 public CompletableFuture<List<PunishmentRecord>> history(UUID u){return CompletableFuture.supplyAsync(()->{List<PunishmentRecord> out=new ArrayList<>();try(PreparedStatement s=conn.prepareStatement("SELECT * FROM punishments WHERE uuid=? ORDER BY id DESC")){s.setString(1,u.toString());try(ResultSet r=s.executeQuery()){while(r.next())out.add(read(r));}}catch(SQLException e){throw new CompletionException(e);}return out;},executor);}
 public CompletableFuture<List<PlayerRecord>> players(String q){return CompletableFuture.supplyAsync(()->{List<PlayerRecord> out=new ArrayList<>();try(PreparedStatement s=conn.prepareStatement("SELECT * FROM players WHERE username LIKE ? ORDER BY last_join DESC LIMIT 500")){s.setString(1,"%"+(q==null?"":q)+"%");try(ResultSet r=s.executeQuery()){while(r.next())out.add(new PlayerRecord(UUID.fromString(r.getString("uuid")),r.getString("username"),r.getString("ip"),r.getString("platform"),r.getString("rank_name"),r.getInt("op")==1,r.getString("server"),r.getString("world"),r.getString("location"),instant(r.getLong("first_join")),instant(r.getLong("last_join")),instant(r.getLong("last_quit"))));}}catch(SQLException e){throw new CompletionException(e);}return out;},executor);}
 public CompletableFuture<Void> updateStatus(long id,PunishmentStatus st){return CompletableFuture.runAsync(()->{try(PreparedStatement s=conn.prepareStatement("UPDATE punishments SET status=? WHERE id=?")){s.setString(1,st.name());s.setLong(2,id);s.executeUpdate();}catch(SQLException e){throw new CompletionException(e);}},executor);}
 public CompletableFuture<Void> expireDue(){return CompletableFuture.runAsync(()->{try(PreparedStatement s=conn.prepareStatement("UPDATE punishments SET status='EXPIRED' WHERE status='ACTIVE' AND permanent=0 AND expires_at>0 AND expires_at<=?")){s.setLong(1,System.currentTimeMillis());s.executeUpdate();}catch(SQLException e){plugin.getLogger().warning("Expiry update failed: "+e.getMessage());}},executor);}
 public void staffAction(String actor,UUID actorUuid,String action,String target,String details){executor.execute(()->{try(PreparedStatement s=conn.prepareStatement("INSERT INTO staff_actions(actor,actor_uuid,action,target,created_at,server,details) VALUES(?,?,?,?,?,?,?)")){s.setString(1,actor);s.setString(2,actorUuid==null?null:actorUuid.toString());s.setString(3,action);s.setString(4,target);s.setLong(5,System.currentTimeMillis());s.setString(6,plugin.serverId());s.setString(7,details);s.executeUpdate();}catch(SQLException e){plugin.getLogger().warning(e.getMessage());}});}
 private PunishmentRecord read(ResultSet r)throws SQLException{String ou=r.getString("operator_uuid");return new PunishmentRecord(r.getLong("id"),UUID.fromString(r.getString("uuid")),r.getString("username"),r.getString("ip"),PunishmentType.valueOf(r.getString("type")),r.getInt("permanent")==1,r.getLong("duration_seconds"),Instant.ofEpochMilli(r.getLong("created_at")),r.getLong("expires_at")==0?null:Instant.ofEpochMilli(r.getLong("expires_at")),r.getString("reason"),r.getString("operator_name"),ou==null?null:UUID.fromString(ou),r.getString("server"),r.getString("world"),r.getString("location"),r.getString("source"),PunishmentStatus.valueOf(r.getString("status")));}
 private Instant instant(long v){return v==0?null:Instant.ofEpochMilli(v);} public void close(){executor.shutdown();try{if(conn!=null)conn.close();}catch(Exception ignored){}}
}
